CREATE TABLE public."calificaciones" ("id" uuid NOT NULL,
"alumno_id" uuid NOT NULL,
"asignacion_id" uuid NOT NULL,
"p1" numeric(4,2),
"p2" numeric(4,2),
"p3" numeric(4,2),
"faltas_p1" smallint,
"faltas_p2" smallint,
"faltas_p3" smallint,
"e1" numeric(4,2),
"folio_e1" text,
"e2" numeric(4,2),
"folio_e2" text,
"e3" numeric(4,2),
"folio_e3" text,
"e4" numeric(4,2),
"folio_e4" text,
"promedio_final" numeric(4,2) GENERATED ALWAYS AS (GREATEST(COALESCE((((COALESCE(p1, (0)::numeric) + COALESCE(p2, (0)::numeric)) + COALESCE(p3, (0)::numeric)) / (NULLIF(((
CASE
    WHEN (p1 IS NOT NULL) THEN 1
    ELSE 0
END +
CASE
    WHEN (p2 IS NOT NULL) THEN 1
    ELSE 0
END) +
CASE
    WHEN (p3 IS NOT NULL) THEN 1
    ELSE 0
END), 0))::numeric), (0)::numeric), COALESCE(e1, (0)::numeric), COALESCE(e2, (0)::numeric), COALESCE(e3, (0)::numeric), COALESCE(e4, (0)::numeric))) STORED,
"capturado_por" uuid,
"updated_at" timestamp with time zone NOT NULL);

