CREATE OR REPLACE FUNCTION public.aplicar_propuesta_calificacion(p_propuesta_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE
  prop record;
  cal_id uuid;
BEGIN
  SELECT * INTO prop FROM public.calificaciones_propuestas WHERE id = p_propuesta_id;
  IF prop.id IS NULL THEN RAISE EXCEPTION 'Propuesta no encontrada'; END IF;
  IF prop.estado <> 'validada' THEN RAISE EXCEPTION 'La propuesta no está validada'; END IF;

  -- Buscar fila existente o crear
  SELECT id INTO cal_id FROM public.calificaciones
    WHERE alumno_id = prop.alumno_id AND asignacion_id = prop.asignacion_id;

  IF cal_id IS NULL THEN
    INSERT INTO public.calificaciones (alumno_id, asignacion_id, capturado_por)
      VALUES (prop.alumno_id, prop.asignacion_id, prop.validada_por)
      RETURNING id INTO cal_id;
  END IF;

  -- Actualizar parcial correspondiente
  IF prop.parcial = 1 THEN
    UPDATE public.calificaciones SET p1 = prop.calificacion, faltas_p1 = COALESCE(prop.faltas, 0),
      capturado_por = prop.validada_por, updated_at = now()
      WHERE id = cal_id;
  ELSIF prop.parcial = 2 THEN
    UPDATE public.calificaciones SET p2 = prop.calificacion, faltas_p2 = COALESCE(prop.faltas, 0),
      capturado_por = prop.validada_por, updated_at = now()
      WHERE id = cal_id;
  ELSIF prop.parcial = 3 THEN
    UPDATE public.calificaciones SET p3 = prop.calificacion, faltas_p3 = COALESCE(prop.faltas, 0),
      capturado_por = prop.validada_por, updated_at = now()
      WHERE id = cal_id;
  END IF;

  RETURN cal_id;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.check_max_orientador_grupos()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE
  total int;
BEGIN
  IF NEW.orientador_id IS NULL OR NEW.deleted_at IS NOT NULL THEN
    RETURN NEW;
  END IF;
  SELECT count(*) INTO total
  FROM public.grupos
  WHERE orientador_id = NEW.orientador_id
    AND deleted_at IS NULL
    AND id <> NEW.id;
  IF total >= 4 THEN
    RAISE EXCEPTION 'Un profesor no puede ser orientador de más de 4 grupos activos (intento %)', total + 1;
  END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.consume_security_limit(p_key text, p_limit integer, p_window_seconds integer)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare n integer;
begin
  if p_key !~ '^[0-9a-f]{64}$' or p_limit not between 1 and 10000 or p_window_seconds not between 1 and 86400 then raise exception 'Invalid rate limit parameters'; end if;
  insert into public.security_rate_limits(key, window_started_at, attempts, expires_at)
  values (p_key, now(), 1, now() + make_interval(secs => p_window_seconds))
  on conflict (key) do update set
    attempts = case when security_rate_limits.expires_at <= now() then 1 else security_rate_limits.attempts + 1 end,
    window_started_at = case when security_rate_limits.expires_at <= now() then now() else security_rate_limits.window_started_at end,
    expires_at = case when security_rate_limits.expires_at <= now() then now() + make_interval(secs => p_window_seconds) else security_rate_limits.expires_at end
  returning attempts into n;
  return n <= p_limit;
end; $function$
;

CREATE OR REPLACE FUNCTION public.crear_usuario_test(p_email text, p_password text, p_nombre text, p_rol text DEFAULT 'profesor'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE
  v_id uuid;
BEGIN
  v_id := gen_random_uuid();

  INSERT INTO auth.users (
    id, instance_id, aud, role, email, encrypted_password,
    email_confirmed_at, raw_app_meta_data, raw_user_meta_data,
    created_at, updated_at, confirmation_token, recovery_token,
    email_change_token_new, email_change
  ) VALUES (
    v_id, '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated',
    p_email, crypt(p_password, gen_salt('bf')),
    now(), '{"provider":"email","providers":["email"]}'::jsonb,
    jsonb_build_object('nombre', p_nombre),
    now(), now(), '', '', '', ''
  );

  INSERT INTO public.perfiles (id, nombre, email, rol)
  VALUES (v_id, p_nombre, p_email, p_rol::rol_usuario);

  RETURN v_id;
END;
$function$
;

