CREATE OR REPLACE FUNCTION public.eval_docente_agregado(p_profesor_id uuid, p_periodo_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(asignacion_id uuid, materia text, grupo text, total integer, promedios jsonb, comentarios text[])
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
  WITH resp AS (
    SELECT r.*
    FROM public.eval_docente_respuestas r
    JOIN public.asignaciones a ON a.id = r.asignacion_id
    WHERE a.profesor_id = p_profesor_id
      AND (p_periodo_id IS NULL OR r.periodo_id = p_periodo_id)
  ),
  agg AS (
    SELECT
      r.asignacion_id,
      COUNT(*)::int AS total,
      jsonb_object_agg(k, v) AS promedios,
      array_agg(r.comentario) FILTER (WHERE r.comentario IS NOT NULL AND length(trim(r.comentario)) > 0) AS comentarios
    FROM resp r,
    LATERAL (
      SELECT k, AVG((val)::numeric) AS v
      FROM (
        SELECT key AS k, value::text AS val
        FROM resp r2
        CROSS JOIN LATERAL jsonb_each_text(r2.respuestas)
        WHERE r2.asignacion_id = r.asignacion_id
      ) s
      GROUP BY k
    ) prom
    GROUP BY r.asignacion_id
  )
  SELECT agg.asignacion_id,
         m.nombre AS materia,
         concat(g.semestre, '° ', g.grupo, ' ', coalesce(g.turno,'')) AS grupo,
         agg.total, agg.promedios, agg.comentarios
  FROM agg
  JOIN public.asignaciones a ON a.id = agg.asignacion_id
  JOIN public.materias m ON m.id = a.materia_id
  JOIN public.grupos g ON g.id = a.grupo_id;
$function$
;

CREATE OR REPLACE FUNCTION public.fn_audit_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare actor uuid:=auth.uid(); actor_email text; before_row jsonb; after_row jsonb; begin
  select email into actor_email from auth.users where id=actor;
  before_row:=public.security_redact_jsonb(to_jsonb(old)); after_row:=public.security_redact_jsonb(to_jsonb(new));
  insert into public.audit_log(tabla,operacion,registro_id,diff,actor_id,actor_email)
    values(tg_table_name,tg_op,coalesce(to_jsonb(new)->>'id',to_jsonb(old)->>'id'),
      case tg_op when 'INSERT' then jsonb_build_object('after',after_row) when 'DELETE' then jsonb_build_object('before',before_row) else jsonb_build_object('before',before_row,'after',after_row) end,actor,actor_email);
  return coalesce(new,old);
end $function$
;

CREATE OR REPLACE FUNCTION public.fn_auditoria_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  insert into public.auditoria(usuario_id,tabla,registro_id,accion,cambios)
    values(auth.uid(),tg_table_name,coalesce(to_jsonb(new)->>'id',to_jsonb(old)->>'id'),lower(tg_op),
      public.security_redact_jsonb(case tg_op when 'INSERT' then jsonb_build_object('after',to_jsonb(new)) when 'DELETE' then jsonb_build_object('before',to_jsonb(old)) else jsonb_build_object('before',to_jsonb(old),'after',to_jsonb(new)) end));
  return coalesce(new,old);
end $function$
;

