CREATE OR REPLACE FUNCTION public.notify_alumno_solicitud_respondida()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE alumno_user uuid;
BEGIN
  IF NEW.estado IS DISTINCT FROM OLD.estado
     AND NEW.estado IN ('respondida','aceptada','rechazada','cerrada') THEN
    SELECT perfil_id INTO alumno_user FROM public.alumnos WHERE id = NEW.alumno_id;
    IF alumno_user IS NOT NULL THEN
      INSERT INTO public.notificaciones(user_id, tipo, titulo, mensaje, url)
      VALUES(alumno_user, 'solicitud',
        'Tu solicitud fue ' || NEW.estado,
        'El profesor respondió a tu solicitud de revisión.',
        '/alumno/solicitudes');
    END IF;
  END IF;
  RETURN NEW;
END $function$
;

CREATE OR REPLACE FUNCTION public.notify_profesor_nueva_solicitud()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE prof_user uuid; alumno_nombre text;
BEGIN
  SELECT p.perfil_id INTO prof_user FROM public.asignaciones a
    JOIN public.profesores p ON p.id = a.profesor_id WHERE a.id = NEW.asignacion_id;
  SELECT nombre INTO alumno_nombre FROM public.alumnos WHERE id = NEW.alumno_id;
  IF prof_user IS NOT NULL THEN
    INSERT INTO public.notificaciones(user_id, tipo, titulo, mensaje, url)
    VALUES(prof_user, 'solicitud', 'Nueva solicitud de revisión',
      COALESCE(alumno_nombre,'Un alumno') || ' solicita revisión de su calificación.',
      '/profesor/solicitudes');
  END IF;
  RETURN NEW;
END $function$
;

CREATE OR REPLACE FUNCTION public.parcial_captura_abierta(p_asignacion uuid, p_parcial integer)
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT COALESCE(
    (SELECT CURRENT_DATE BETWEEN COALESCE(abre_captura, '1900-01-01')
                              AND COALESCE(cierra_captura, '2999-12-31')
     FROM public.parciales_config pc
     JOIN public.asignaciones a ON a.ciclo_id = pc.ciclo_id
     WHERE a.id = p_asignacion AND pc.numero = p_parcial
     LIMIT 1),
    true
  );
$function$
;

CREATE OR REPLACE FUNCTION public.public_document_version_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if tg_op='UPDATE' and old.publicado_en is not null then
    if row(new.pdf_url,new.docx_url,new.pdf_storage_path,new.docx_storage_path,new.version,new.ciclo_id)
       is distinct from row(old.pdf_url,old.docx_url,old.pdf_storage_path,old.docx_storage_path,old.version,old.ciclo_id) then
      raise exception 'Crea una nueva versión del documento publicado' using errcode='23514';
    end if;
    new.publicado_en:=old.publicado_en;
  elsif new.publicada then new.publicado_en:=now();
  else new.publicado_en:=null;
  end if;
  return new;
end $function$
;

CREATE OR REPLACE FUNCTION public.puede_ver_perfil(perfil_objetivo uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select perfil_objetivo=auth.uid() or public.es_admin() or exists(select 1 from public.alumnos a where a.perfil_id=perfil_objetivo and public.security_can_read_student(a.id)) or exists(select 1 from public.profesores p where p.perfil_id=perfil_objetivo and public.security_can_contact_professor(p.id));
$function$
;

CREATE OR REPLACE FUNCTION public.rls_auto_enable()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.security_backup_snapshot()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
declare t record; rows jsonb; data jsonb:='{}'; cols jsonb:='{}'; begin
  for t in select tablename from pg_tables where schemaname='public' and tablename not in
    ('security_rate_limits','security_events','imports_credenciales','push_webhook_config','push_subscriptions') order by tablename
  loop
    execute format('select coalesce(jsonb_agg(to_jsonb(row)),''[]''::jsonb) from public.%I row',t.tablename) into rows;
    data:=data||jsonb_build_object(t.tablename,rows);
    select jsonb_agg(jsonb_build_object('name',column_name,'type',udt_schema||'.'||udt_name,'nullable',is_nullable,'default',column_default) order by ordinal_position) into rows
      from information_schema.columns where table_schema='public' and table_name=t.tablename;
    cols:=cols||jsonb_build_object(t.tablename,rows);
  end loop;
  return jsonb_build_object('version',1,'created_at',now(),'data',data,'columns',cols,
    'storage',(select coalesce(jsonb_agg(jsonb_build_object('bucket_id',bucket_id,'name',name,'size',coalesce(metadata->>'size','0'))),'[]'::jsonb) from storage.objects where bucket_id<>'security-backups'),
    'buckets',(select coalesce(jsonb_agg(to_jsonb(b)),'[]'::jsonb) from storage.buckets b where id<>'security-backups'));
end $function$
;

CREATE OR REPLACE FUNCTION public.security_backup_validate(p_snapshot jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
declare entry record; actual bigint; expected bigint; total bigint:=0; tables integer:=0; begin
  if p_snapshot->>'version'<>'1' or jsonb_typeof(p_snapshot->'data')<>'object' then raise exception 'Invalid snapshot'; end if;
  for entry in select key,value from jsonb_each(p_snapshot->'data') loop
    if entry.key !~ '^[a-z_]+$' or not exists(select 1 from pg_tables where schemaname='public' and tablename=entry.key) then raise exception 'Invalid snapshot table'; end if;
    execute format('create temp table security_restore_check (like public.%I including constraints) on commit drop',entry.key);
    execute format('insert into pg_temp.security_restore_check select * from jsonb_populate_recordset(null::public.%I,$1)',entry.key) using entry.value;
    select count(*) into actual from pg_temp.security_restore_check;
    expected:=jsonb_array_length(entry.value);
    if actual<>expected then raise exception 'Snapshot count mismatch'; end if;
    total:=total+actual; tables:=tables+1;
    drop table pg_temp.security_restore_check;
  end loop;
  return jsonb_build_object('ok',true,'tables',tables,'rows',total);
end $function$
;

CREATE OR REPLACE FUNCTION public.security_can_contact_professor(p_profesor_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select public.security_session_valid() and (public.es_admin()
    or exists(select 1 from public.profesores p where p.id=p_profesor_id and p.perfil_id=auth.uid())
    or exists(select 1 from public.asignaciones a join public.grupos g on g.id=a.grupo_id join public.profesores p on p.id=g.orientador_id where a.profesor_id=p_profesor_id and p.perfil_id=auth.uid())
    or exists(select 1 from public.asignaciones a join public.inscripciones i on i.grupo_id=a.grupo_id and i.ciclo_id=a.ciclo_id
      join public.alumnos al on al.id=i.alumno_id where a.profesor_id=p_profesor_id and i.estatus='activa' and al.perfil_id=auth.uid())
    or exists(select 1 from public.grupos g join public.inscripciones i on i.grupo_id=g.id join public.alumnos al on al.id=i.alumno_id
      where g.orientador_id=p_profesor_id and i.estatus='activa' and al.perfil_id=auth.uid()));
$function$
;

CREATE OR REPLACE FUNCTION public.security_can_read_assignment(p_asignacion_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select public.security_session_valid() and (public.es_admin()
    or exists(select 1 from public.asignaciones a join public.profesores p on p.id=a.profesor_id where a.id=p_asignacion_id and p.perfil_id=auth.uid())
    or exists(select 1 from public.asignaciones a join public.grupos g on g.id=a.grupo_id join public.profesores p on p.id=g.orientador_id where a.id=p_asignacion_id and p.perfil_id=auth.uid())
    or exists(select 1 from public.asignaciones a join public.inscripciones i on i.grupo_id=a.grupo_id and i.ciclo_id=a.ciclo_id
      join public.alumnos al on al.id=i.alumno_id where a.id=p_asignacion_id and i.estatus='activa' and al.perfil_id=auth.uid()));
$function$
;

CREATE OR REPLACE FUNCTION public.security_can_read_notice(p_aviso_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select public.security_session_valid() and exists (
    select 1 from public.avisos v where v.id=p_aviso_id and (
      public.es_admin() or v.autor_id=auth.uid() or v.alcance='todos'
      or (v.alcance='profesores' and exists(select 1 from public.profesores p where p.perfil_id=auth.uid()))
      or (v.alcance='alumno' and exists(select 1 from public.alumnos al where al.id=v.alumno_id and al.perfil_id=auth.uid()))
      or (v.alcance in ('grupo','grupos') and (
        exists(select 1 from public.inscripciones i join public.alumnos al on al.id=i.alumno_id
          where i.grupo_id=any(v.grupo_ids) and i.estatus='activa' and al.perfil_id=auth.uid())
        or exists(select 1 from public.asignaciones a join public.profesores p on p.id=a.profesor_id
          where a.grupo_id=any(v.grupo_ids) and p.perfil_id=auth.uid())
        or exists(select 1 from public.grupos g join public.profesores p on p.id=g.orientador_id
          where g.id=any(v.grupo_ids) and p.perfil_id=auth.uid())
      ))
    )
  );
$function$
;

CREATE OR REPLACE FUNCTION public.security_can_read_student(p_alumno_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select public.security_session_valid() and (
    public.es_admin() or exists(select 1 from public.alumnos a where a.id=p_alumno_id and a.perfil_id=auth.uid())
    or public.security_is_student_counselor(p_alumno_id)
    or exists(select 1 from public.inscripciones i join public.asignaciones a on a.grupo_id=i.grupo_id and a.ciclo_id=i.ciclo_id
      join public.profesores p on p.id=a.profesor_id where i.alumno_id=p_alumno_id and i.estatus='activa' and p.perfil_id=auth.uid()));
$function$
;

CREATE OR REPLACE FUNCTION public.security_cleanup()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  delete from public.security_rate_limits where expires_at < now() - interval '1 day';
  delete from public.security_events where created_at < now() - interval '90 days';
  update public.imports_credenciales set credentials_ciphertext=null where expires_at<=now() and credentials_ciphertext is not null;
end; $function$
;

CREATE OR REPLACE FUNCTION public.security_cycle_diagnostic(p_cycle uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare c public.ciclos_escolares; missing_grades integer; no_subjects integer; inconsistent integer; reviews integer; payments integer; enrolled integer;
begin
  if not public.security_session_valid() or not public.es_admin() then raise exception 'Acceso no autorizado' using errcode='42501'; end if;
  select * into c from public.ciclos_escolares where id=p_cycle;
  if not found then raise exception 'Ciclo inexistente'; end if;
  select count(*) into enrolled from public.inscripciones where ciclo_id=p_cycle and estatus='activa';
  select count(*) into inconsistent from public.inscripciones i join public.grupos g on g.id=i.grupo_id where i.ciclo_id=p_cycle and g.ciclo_id<>p_cycle;
  select count(*) into no_subjects from public.inscripciones i where i.ciclo_id=p_cycle and i.estatus='activa' and not exists(select 1 from public.asignaciones a where a.ciclo_id=p_cycle and a.grupo_id=i.grupo_id);
  select count(*) into missing_grades from public.inscripciones i join public.asignaciones a on a.grupo_id=i.grupo_id and a.ciclo_id=i.ciclo_id
    left join public.calificaciones k on k.alumno_id=i.alumno_id and k.asignacion_id=a.id
    where i.ciclo_id=p_cycle and i.estatus='activa' and (k.id is null or k.p1 is null or k.p2 is null or k.p3 is null or k.promedio_final is null);
  select count(*) into reviews from public.solicitudes_revision r join public.asignaciones a on a.id=r.asignacion_id where a.ciclo_id=p_cycle and r.estado in ('abierta','respondida');
  reviews:=reviews+(select count(*) from public.solicitudes_parcial where ciclo_id=p_cycle and estado='pendiente');
  select count(*) into payments from public.pagos p where p.validado_en is null and p.rechazado_motivo is null and exists(select 1 from public.inscripciones i where i.ciclo_id=p_cycle and i.alumno_id=p.alumno_id);
  return jsonb_build_object('version',1,'inscripciones',enrolled,'calificaciones_incompletas',missing_grades,'sin_materias',no_subjects,'inscripciones_inconsistentes',inconsistent,'revisiones_pendientes',reviews,'pagos_por_revisar',payments,
    'fechas_validas',c.fecha_inicio is not null and c.fecha_fin is not null and c.fecha_inicio<=c.fecha_fin and c.fecha_fin<=(now() at time zone 'America/Mexico_City')::date,
    'puede_cerrar',c.cerrado_en is null and enrolled>0 and missing_grades=0 and no_subjects=0 and inconsistent=0 and reviews=0 and c.fecha_inicio is not null and c.fecha_fin is not null and c.fecha_inicio<=c.fecha_fin and c.fecha_fin<=(now() at time zone 'America/Mexico_City')::date);
end $function$
;

CREATE OR REPLACE FUNCTION public.security_cycle_transition(p_cycle uuid, p_action text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare c public.ciclos_escolares; d jsonb;
begin
  if not public.security_session_valid() or not public.es_admin() then raise exception 'Acceso no autorizado' using errcode='42501'; end if;
  if p_action not in ('activar','cerrar','reabrir') or length(trim(coalesce(p_reason,''))) not between 10 and 1000 then raise exception 'Acción o motivo inválido'; end if;
  -- Serialize transitions and lock academic writers out until the transaction commits.
  perform pg_advisory_xact_lock(2212026);
  select * into c from public.ciclos_escolares where id=p_cycle for update;
  if not found then raise exception 'Ciclo inexistente'; end if;
  d:=public.security_cycle_diagnostic(p_cycle);
  if p_action='activar' then
    if c.cerrado_en is not null then raise exception 'Reabre el ciclo antes de activarlo'; end if;
    update public.ciclos_escolares set activo=false where activo and id<>p_cycle;
    update public.ciclos_escolares set activo=true where id=p_cycle;
  elsif p_action='cerrar' then
    if not (d->>'puede_cerrar')::boolean then raise exception 'Resuelve las incidencias del diagnóstico antes de cerrar'; end if;
    update public.ciclos_escolares set activo=false,cerrado_en=now(),cerrado_por=auth.uid() where id=p_cycle;
  else
    if c.cerrado_en is null then raise exception 'El ciclo ya está abierto'; end if;
    update public.ciclos_escolares set cerrado_en=null,cerrado_por=null where id=p_cycle;
  end if;
  insert into public.ciclo_historial(ciclo_id,accion,motivo,diagnostico,actor_id) values(p_cycle,p_action,trim(p_reason),d,auth.uid());
  return d;
end $function$
;

CREATE OR REPLACE FUNCTION public.security_cycle_write_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare row_data jsonb; cid uuid; closed_at timestamptz;
begin
  for row_data in select value from jsonb_array_elements(case when tg_op='INSERT' then jsonb_build_array(to_jsonb(new)) when tg_op='DELETE' then jsonb_build_array(to_jsonb(old)) else jsonb_build_array(to_jsonb(old),to_jsonb(new)) end) loop
    if tg_table_name in ('asignaciones','inscripciones','solicitudes_parcial') then cid:=(row_data->>'ciclo_id')::uuid;
    elsif tg_table_name='entregas_tarea' then select a.ciclo_id into cid from public.tareas t join public.asignaciones a on a.id=t.asignacion_id where t.id=(row_data->>'tarea_id')::uuid;
    else select ciclo_id into cid from public.asignaciones where id=(row_data->>'asignacion_id')::uuid; end if;
    select cerrado_en into closed_at from public.ciclos_escolares where id=cid for share;
    if closed_at is not null then raise exception 'Ciclo cerrado: solicita reapertura con motivo antes de modificar registros'; end if;
  end loop;
  if tg_op='DELETE' then return old; end if;
  return new;
end $function$
;

CREATE OR REPLACE FUNCTION public.security_exam_answer(p_intento_id uuid, p_actor_id uuid, p_answers jsonb, p_submit boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare i public.examen_intentos; e public.examenes; v_question public.examen_preguntas;
  v_key text; v_answer text; v_correct boolean; v_points numeric;
  v_deadline timestamptz; v_total numeric; v_score numeric; v_pending boolean; v_teacher uuid;
begin
  select * into i from public.examen_intentos where id=p_intento_id for update;
  if i.id is null or not exists(select 1 from public.alumnos where id=i.alumno_id and perfil_id=p_actor_id)
    then raise exception 'Intento no disponible.'; end if;
  if i.estado<>'en_curso' then
    if p_submit then return jsonb_build_object('ok',true); end if;
    raise exception 'El examen ya fue entregado.';
  end if;
  select * into e from public.examenes where id=i.examen_id;
  v_deadline:=least(e.fecha_cierre,i.inicio+make_interval(mins=>coalesce(e.duracion_min,60)));
  if now()<e.fecha_apertura then raise exception 'El examen todavía no abre.'; end if;
  if now()>v_deadline and not p_submit then raise exception 'El tiempo del examen terminó.'; end if;
  if jsonb_typeof(p_answers) is distinct from 'object' or octet_length(p_answers::text)>100000
    then raise exception 'Respuestas inválidas.'; end if;
  -- Late submissions freeze the answers already saved before the deadline.
  if now()<=v_deadline then
    for v_key,v_answer in select key,value from jsonb_each_text(p_answers) loop
      select * into v_question from public.examen_preguntas where id=v_key::uuid and examen_id=e.id;
      if v_question.id is null or length(v_answer)>10000 then raise exception 'Respuesta inválida.'; end if;
      v_answer:=btrim(v_answer); v_correct:=null; v_points:=null;
      if v_question.tipo in ('opcion_multiple','verdadero_falso') then
        if v_answer<>'' and not exists(select 1 from jsonb_array_elements(v_question.opciones) o where o->>'clave'=v_answer)
          then raise exception 'Opción inválida.'; end if;
        v_correct:=v_answer=v_question.respuesta_correcta; v_points:=case when v_correct then v_question.puntos else 0 end;
      end if;
      insert into public.examen_respuestas(intento_id,pregunta_id,respuesta,correcta,puntos_obtenidos)
        values(i.id,v_question.id,v_answer,v_correct,v_points)
        on conflict(intento_id,pregunta_id) do update set respuesta=excluded.respuesta,
          correcta=excluded.correcta,puntos_obtenidos=excluded.puntos_obtenidos;
    end loop;
  end if;
  if p_submit then
    select coalesce(sum(puntos),0) into v_total from public.examen_preguntas where examen_id=e.id;
    select coalesce(sum(r.puntos_obtenidos),0),coalesce(bool_or(q.tipo='abierta' and btrim(coalesce(r.respuesta,''))<>'' and r.puntos_obtenidos is null),false)
      into v_score,v_pending from public.examen_respuestas r join public.examen_preguntas q on q.id=r.pregunta_id
      where r.intento_id=i.id and q.examen_id=e.id;
    update public.examen_intentos set fin=now(),estado=case when v_pending then 'enviado' else 'calificado' end,
      calificacion=case when v_pending then null when v_total>0 then round(v_score/v_total*10,1) else 0 end where id=i.id;
    if v_pending then
      select p.perfil_id into v_teacher from public.asignaciones a join public.profesores p on p.id=a.profesor_id where a.id=e.asignacion_id;
      if v_teacher is not null then insert into public.notificaciones(user_id,tipo,titulo,mensaje,url)
        values(v_teacher,'examen','Examen por calificar: '||e.titulo,'Un alumno entregó respuestas abiertas.','/profesor/examenes'); end if;
    end if;
  end if;
  return jsonb_build_object('ok',true);
end $function$
;

CREATE OR REPLACE FUNCTION public.security_exam_grade(p_respuesta_id uuid, p_actor_id uuid, p_points numeric, p_correct boolean)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_attempt uuid; i public.examen_intentos; q public.examen_preguntas;
  v_total numeric; v_score numeric; v_pending boolean;
begin
  select intento_id into v_attempt from public.examen_respuestas where id=p_respuesta_id;
  select * into i from public.examen_intentos where id=v_attempt for update;
  if i.id is null or i.estado='en_curso' then raise exception 'El alumno todavía no entrega este examen.'; end if;
  if not exists(select 1 from public.examenes e join public.asignaciones a on a.id=e.asignacion_id
    join public.profesores p on p.id=a.profesor_id where e.id=i.examen_id and p.perfil_id=p_actor_id)
    and not exists(select 1 from public.perfiles where id=p_actor_id and activo and rol in ('admin','staff','director'))
    then raise exception 'Solo el docente asignado puede calificar.'; end if;
  select p.* into q from public.examen_respuestas r join public.examen_preguntas p on p.id=r.pregunta_id
    where r.id=p_respuesta_id and p.examen_id=i.examen_id;
  if q.id is null or q.tipo<>'abierta' or p_points is null or p_points<0 or p_points>q.puntos then raise exception 'Puntuación inválida.'; end if;
  update public.examen_respuestas set puntos_obtenidos=p_points,correcta=p_correct where id=p_respuesta_id;
  select coalesce(sum(puntos),0) into v_total from public.examen_preguntas where examen_id=i.examen_id;
  select coalesce(sum(r.puntos_obtenidos),0),coalesce(bool_or(p.tipo='abierta' and btrim(coalesce(r.respuesta,''))<>'' and r.puntos_obtenidos is null),false)
    into v_score,v_pending from public.examen_respuestas r join public.examen_preguntas p on p.id=r.pregunta_id
    where r.intento_id=i.id and p.examen_id=i.examen_id;
  update public.examen_intentos set estado=case when v_pending then 'enviado' else 'calificado' end,
    calificacion=case when v_pending then null when v_total>0 then round(v_score/v_total*10,1) else 0 end where id=i.id;
  return i.examen_id;
end $function$
;

CREATE OR REPLACE FUNCTION public.security_exam_start(p_examen_id uuid, p_actor_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare e public.examenes; v_student uuid; v_id uuid; v_number integer; v_count integer;
begin
  select * into e from public.examenes where id=p_examen_id for update;
  select id into v_student from public.alumnos where perfil_id=p_actor_id;
  if e.id is null or v_student is null or not exists (
    select 1 from public.asignaciones a join public.inscripciones i
      on i.grupo_id=a.grupo_id and i.ciclo_id=a.ciclo_id
    where a.id=e.asignacion_id and i.alumno_id=v_student and i.estatus='activa'
  ) then raise exception 'Examen no disponible.'; end if;
  select id into v_id from public.examen_intentos
    where examen_id=e.id and alumno_id=v_student and estado='en_curso' order by numero desc limit 1;
  if v_id is not null then return v_id; end if;
  if now()<e.fecha_apertura or now()>e.fecha_cierre then raise exception 'El examen está fuera de su horario.'; end if;
  if not exists(select 1 from public.examen_preguntas where examen_id=e.id) then raise exception 'El examen todavía no tiene preguntas.'; end if;
  select count(*),coalesce(max(numero),0)+1 into v_count,v_number
    from public.examen_intentos where examen_id=e.id and alumno_id=v_student;
  if v_count>=coalesce(e.intentos_max,1) then raise exception 'Has agotado los intentos.'; end if;
  insert into public.examen_intentos(examen_id,alumno_id,numero,estado)
    values(e.id,v_student,v_number,'en_curso') returning id into v_id;
  return v_id;
end $function$
;

CREATE OR REPLACE FUNCTION public.security_expired_upload_paths()
 RETURNS TABLE(name text)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select o.name from storage.objects o where bucket_id='security-uploads'
    and created_at<now()-interval '3 hours' order by created_at limit 1000;
$function$
;

CREATE OR REPLACE FUNCTION public.security_is_student_counselor(p_alumno_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select public.security_session_valid() and exists(select 1 from public.inscripciones i join public.grupos g on g.id=i.grupo_id
    join public.profesores p on p.id=g.orientador_id where i.alumno_id=p_alumno_id and i.estatus='activa' and p.perfil_id=auth.uid());
$function$
;

CREATE OR REPLACE FUNCTION public.security_latest_risk(p_cycle uuid)
 RETURNS SETOF riesgo_snapshots
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select distinct on (alumno_id) * from public.riesgo_snapshots where ciclo_id=p_cycle order by alumno_id,created_at desc;
$function$
;

CREATE OR REPLACE FUNCTION public.security_mobile_classmates()
 RETURNS TABLE(id uuid, nombre text, apellido_paterno text, apellido_materno text, foto_url text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select distinct other.id,other.nombre,other.apellido_paterno,other.apellido_materno,other.foto_url
  from public.alumnos me join public.inscripciones mine on mine.alumno_id=me.id and mine.estatus='activa'
  join public.inscripciones theirs on theirs.grupo_id=mine.grupo_id and theirs.ciclo_id=mine.ciclo_id and theirs.estatus='activa'
  join public.alumnos other on other.id=theirs.alumno_id and other.deleted_at is null
  where public.security_session_valid() and me.perfil_id=auth.uid() and other.id<>me.id;
$function$
;

CREATE OR REPLACE FUNCTION public.security_mobile_submit_task(p_actor_id uuid, p_task_id uuid, p_comment text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_student uuid; v_task public.tareas; v_id uuid;
begin
  select al.id into v_student from public.alumnos al join public.perfiles p on p.id=al.perfil_id
    where al.perfil_id=p_actor_id and al.deleted_at is null and p.activo and p.rol='alumno';
  select * into v_task from public.tareas where id=p_task_id for update;
  if v_student is null or v_task.id is null or not exists (
    select 1 from public.asignaciones a join public.inscripciones i on i.grupo_id=a.grupo_id and i.ciclo_id=a.ciclo_id
    where a.id=v_task.asignacion_id and i.alumno_id=v_student and i.estatus='activa'
  ) then raise exception 'Tarea no disponible.'; end if;
  if p_comment is null or length(btrim(p_comment))<1 or length(p_comment)>100000 then raise exception 'Respuesta inválida.'; end if;
  if v_task.fecha_apertura>now() then raise exception 'La tarea todavía no abre.'; end if;
  if v_task.cierra_estricto and v_task.fecha_entrega<now() then raise exception 'La tarea ya cerró.'; end if;
  insert into public.entregas_tarea(tarea_id,alumno_id,comentario,entregado_at,estado)
    values(v_task.id,v_student,btrim(p_comment),now(),'entregada')
    on conflict(tarea_id,alumno_id) do update set comentario=excluded.comentario,entregado_at=excluded.entregado_at,estado=excluded.estado
      where public.entregas_tarea.calificacion is null
    returning id into v_id;
  if v_id is null then raise exception 'La entrega ya fue calificada.'; end if;
  return v_id;
end $function$
;

CREATE OR REPLACE FUNCTION public.security_payment_review(p_actor_id uuid, p_pago_id uuid, p_cargo_id uuid, p_approve boolean, p_reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_payment public.pagos; v_cargo public.cargos; v_paid numeric;
begin
  if not exists(select 1 from public.perfiles where id=p_actor_id and activo and rol in ('admin','staff','director','finanzas'))
    then raise exception 'No autorizado.'; end if;
  select cargo_id into v_payment.cargo_id from public.pagos where id=p_pago_id;
  if v_payment.cargo_id is null or v_payment.cargo_id<>p_cargo_id then raise exception 'El pago no corresponde al cargo.'; end if;
  select * into v_cargo from public.cargos where id=p_cargo_id for update;
  select * into v_payment from public.pagos where id=p_pago_id for update;
  if v_payment.validado_en is not null then raise exception 'El pago ya fue validado.'; end if;
  if not p_approve and (p_reason is null or length(btrim(p_reason))<3 or length(p_reason)>500)
    then raise exception 'Indica el motivo del rechazo.'; end if;
  if p_approve then
    if v_payment.comprobante_url is null then raise exception 'El pago no tiene comprobante.'; end if;
    update public.pagos set validado_por=p_actor_id,validado_en=now(),rechazado_motivo=null,
      folio_recibo='R-'||extract(year from now())::text||'-'||upper(left(replace(gen_random_uuid()::text,'-',''),12)) where id=v_payment.id;
  else
    update public.pagos set rechazado_motivo=btrim(p_reason),validado_por=null,validado_en=null where id=v_payment.id;
  end if;
  select coalesce(sum(monto_pagado),0) into v_paid from public.pagos where cargo_id=v_cargo.id and validado_en is not null;
  update public.cargos set estatus=case when v_paid>=v_cargo.monto then 'pagado' else 'pendiente' end where id=v_cargo.id;
end $function$
;

CREATE OR REPLACE FUNCTION public.security_payment_submit(p_actor_id uuid, p_cargo_id uuid, p_method text, p_reference text, p_path text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_cargo public.cargos; v_student uuid; v_id uuid;
begin
  select id into v_student from public.alumnos where perfil_id=p_actor_id;
  select * into v_cargo from public.cargos where id=p_cargo_id for update;
  if v_student is null or v_cargo.id is null or v_cargo.alumno_id<>v_student then raise exception 'Cargo no disponible.'; end if;
  if v_cargo.estatus not in ('pendiente','vencido') then raise exception 'Este cargo ya está pagado o en revisión.'; end if;
  if p_method not in ('transferencia','ventanilla','efectivo') or length(p_reference)>200 then raise exception 'Datos del pago inválidos.'; end if;
  if not exists(select 1 from storage.objects where bucket_id='comprobantes' and name=p_path)
    or split_part(p_path,'/',1)<>v_student::text then raise exception 'No se recibió el comprobante.'; end if;
  insert into public.pagos(cargo_id,alumno_id,monto_pagado,metodo,referencia,fecha_pago,comprobante_url,subido_por)
    values(v_cargo.id,v_student,v_cargo.monto,p_method,nullif(btrim(p_reference),''),current_date,p_path,p_actor_id) returning id into v_id;
  update public.cargos set estatus='en_revision' where id=v_cargo.id;
  return v_id;
end $function$
;

CREATE OR REPLACE FUNCTION public.security_redact_jsonb(value jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare result jsonb; begin
  if jsonb_typeof(value)='object' then
    select coalesce(jsonb_object_agg(key, public.security_redact_jsonb(val)), '{}'::jsonb) into result
    from jsonb_each(value) as entry(key,val) where key !~* '(password|token|secret|cookie|credential|credencial|authorization|service_role)';
  elsif jsonb_typeof(value)='array' then
    select coalesce(jsonb_agg(public.security_redact_jsonb(val)), '[]'::jsonb) into result from jsonb_array_elements(value) as entry(val);
  else result:=value; end if;
  return result;
end $function$
;

CREATE OR REPLACE FUNCTION public.security_revoke_user_sessions(p_user_id uuid, p_keep_session uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  delete from auth.sessions where user_id=p_user_id and (p_keep_session is null or id<>p_keep_session);
$function$
;

CREATE OR REPLACE FUNCTION public.security_save_risk_run(p_cycle uuid, p_rows jsonb, p_origin text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare run_id uuid; newly_critical uuid[]; recipients record; alerts integer:=0;
begin
  if p_origin not in ('cron_reglas','manual_admin') or jsonb_typeof(p_rows)<>'array' then raise exception 'Entrada inválida'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_cycle::text,221));
  insert into public.riesgo_ejecuciones(ciclo_id,origen) values(p_cycle,p_origin) on conflict do nothing returning id into run_id;
  if run_id is null then return jsonb_build_object('duplicada',true,'notificaciones',0); end if;
  if exists(select 1 from jsonb_to_recordset(p_rows) as r(alumno_id uuid,score int,nivel text) where score not between 0 and 100 or nivel not in ('bajo','medio','alto','critico') or not exists(select 1 from public.inscripciones i where i.alumno_id=r.alumno_id and i.ciclo_id=p_cycle and i.estatus='activa')) then raise exception 'Resultado de riesgo inválido'; end if;
  select array_agg(r.alumno_id) into newly_critical from jsonb_to_recordset(p_rows) as r(alumno_id uuid,nivel text)
    where r.nivel='critico' and coalesce((select nivel from public.riesgo_snapshots s where s.ciclo_id=p_cycle and s.alumno_id=r.alumno_id order by created_at desc limit 1),'bajo')<>'critico';
  insert into public.riesgo_snapshots(alumno_id,ciclo_id,score,nivel,factores,recomendacion,generado_por)
    select alumno_id,p_cycle,score,nivel,factores,recomendacion,p_origin from jsonb_to_recordset(p_rows) as r(alumno_id uuid,score smallint,nivel text,factores jsonb,recomendacion text);
  for recipients in select pr.perfil_id,count(distinct i.alumno_id) n from public.inscripciones i join public.grupos g on g.id=i.grupo_id join public.profesores pr on pr.id=g.orientador_id join public.perfiles p on p.id=pr.perfil_id and p.activo
    where i.ciclo_id=p_cycle and i.estatus='activa' and i.alumno_id=any(newly_critical) group by pr.perfil_id loop
    insert into public.notificaciones(user_id,tipo,titulo,mensaje,url) values(recipients.perfil_id,'riesgo','Alumnos en riesgo crítico',recipients.n||' alumno(s) entraron en riesgo crítico. Revisa su seguimiento.','/profesor/riesgo');
    alerts:=alerts+1;
  end loop;
  return jsonb_build_object('duplicada',false,'notificaciones',alerts);
end $function$
;

CREATE OR REPLACE FUNCTION public.security_session_alive()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select exists(select 1 from public.perfiles p join auth.sessions s on s.user_id=p.id
    where p.id=auth.uid() and p.activo and s.id=nullif(auth.jwt()->>'session_id','')::uuid
      and (p.password_reset_at is null or coalesce((auth.jwt()->>'iat')::bigint,0)>=extract(epoch from date_trunc('second',p.password_reset_at))));
$function$
;

CREATE OR REPLACE FUNCTION public.security_session_valid()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select public.security_session_alive() and exists(select 1 from public.perfiles p where p.id=auth.uid() and p.activo
    and not coalesce(p.debe_cambiar_password,false)
    and (p.rol not in ('admin','staff','director','finanzas') or coalesce(auth.jwt()->>'aal','aal1')='aal2')
    and (coalesce(auth.jwt()->>'aal','aal1')='aal2' or not exists(select 1 from auth.mfa_factors f where f.user_id=p.id and f.status='verified')));
$function$
;

CREATE OR REPLACE FUNCTION public.security_storage_read_allowed(p_bucket text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select public.security_session_valid() or exists(select 1 from storage.buckets where id=p_bucket and public);
$function$
;

CREATE OR REPLACE FUNCTION public.security_storage_resource_scope(p_bucket text, p_name text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select case
    when p_bucket not in ('tareas','portafolio','chat-grupal') then true
    when public.es_admin() then true
    when p_bucket='tareas' then exists(
      select 1 from public.entregas_tarea e join public.alumnos al on al.id=e.alumno_id
      where e.archivo_url=p_name and al.perfil_id=auth.uid()
    ) or exists(
      select 1 from public.tareas t join public.asignaciones a on a.id=t.asignacion_id
      join public.profesores p on p.id=a.profesor_id
      where t.id::text=split_part(p_name,'/',1) and p.perfil_id=auth.uid()
    )
    when p_bucket='portafolio' then exists(select 1 from public.alumnos al
      where al.id::text=split_part(p_name,'/',1) and public.security_can_read_student(al.id))
    when p_bucket='chat-grupal' then exists(select 1 from public.asignaciones a
      where a.id::text=split_part(p_name,'/',1) and public.security_can_read_assignment(a.id))
    else false end;
$function$
;

CREATE OR REPLACE FUNCTION public.set_solicitud_orientador()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE
  oid uuid;
BEGIN
  IF NEW.orientador_id IS NOT NULL THEN RETURN NEW; END IF;
  SELECT g.orientador_id INTO oid
    FROM public.asignaciones a
    JOIN public.grupos g ON g.id = a.grupo_id
   WHERE a.id = NEW.asignacion_id;
  NEW.orientador_id := oid;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.slug_email_alumno(p_nombre text, p_apellido text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE
  base text;
BEGIN
  base := lower(unaccent(coalesce(p_nombre, '')));
  base := regexp_replace(base, '[^a-z0-9]+', '', 'g');
  IF base = '' THEN base := 'alumno'; END IF;
  base := base || '.' || regexp_replace(lower(unaccent(coalesce(p_apellido, ''))), '[^a-z0-9]+', '', 'g');
  RETURN base;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.touch_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  new.updated_at := now();
  return new;
end $function$
;

CREATE OR REPLACE FUNCTION public.trg_notificacion_push()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE
  cfg push_webhook_config%ROWTYPE;
BEGIN
  SELECT * INTO cfg FROM push_webhook_config WHERE id = 1;
  IF cfg.enabled IS NOT TRUE OR cfg.webhook_url IS NULL THEN
    RETURN NEW;
  END IF;
  PERFORM net.http_post(
    url := cfg.webhook_url,
    headers := jsonb_build_object(
      'content-type', 'application/json',
      'x-webhook-secret', COALESCE(cfg.webhook_secret, '')
    ),
    body := jsonb_build_object(
      'perfil_id', NEW.user_id,
      'title', NEW.titulo,
      'body', NEW.mensaje,
      'url', NEW.url
    )
  );
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RETURN NEW;
END;
$function$
;

