CREATE VIEW public."companeros_directorio" WITH (security_invoker=true) AS SELECT DISTINCT a.id,
    a.nombre,
    a.apellido_paterno,
    a.apellido_materno,
    a.foto_url
   FROM alumnos a
     JOIN inscripciones suya ON suya.alumno_id = a.id AND suya.estatus = 'activa'::text
  WHERE a.deleted_at IS NULL AND (EXISTS ( SELECT 1
           FROM inscripciones mia
          WHERE mia.alumno_id = mi_alumno_id() AND mia.estatus = 'activa'::text AND mia.grupo_id = suya.grupo_id AND mia.ciclo_id = suya.ciclo_id));

CREATE VIEW public."vista_estado_cuenta" WITH (security_invoker=on) AS SELECT c.id AS cargo_id,
    c.alumno_id,
    cp.clave,
    cp.nombre AS concepto,
    cp.tipo,
    c.monto,
    c.fecha_limite,
    c.estatus,
    c.notas,
    ( SELECT json_agg(json_build_object('id', p.id, 'monto', p.monto_pagado, 'fecha', p.fecha_pago, 'metodo', p.metodo, 'referencia', p.referencia, 'validado', p.validado_en IS NOT NULL, 'folio_recibo', p.folio_recibo, 'comprobante_url', p.comprobante_url) ORDER BY p.subido_en DESC) AS json_agg
           FROM pagos p
          WHERE p.cargo_id = c.id) AS intentos_pago,
    c.created_at
   FROM cargos c
     JOIN conceptos_pago cp ON cp.id = c.concepto_id;

CREATE VIEW public."vista_historial_academico" WITH (security_invoker=on) AS SELECT a.id AS alumno_id,
    a.curp,
    a.matricula,
    (((a.nombre || ' '::text) || a.apellido_paterno) || ' '::text) || COALESCE(a.apellido_materno, ''::text) AS alumno,
    ce.id AS ciclo_id,
    ce.codigo AS ciclo,
    ce.periodo,
    g.grado,
    g.semestre,
    g.grupo,
    g.turno,
    m.id AS materia_id,
    m.nombre AS materia,
    m.campo_disciplinar_id,
    m.tipo AS tipo_materia,
    m.horas_semestrales,
    c.p1,
    c.p2,
    c.p3,
    c.faltas_p1,
    c.faltas_p2,
    c.faltas_p3,
    c.e1,
    c.folio_e1,
    c.e2,
    c.folio_e2,
    c.e3,
    c.folio_e3,
    c.e4,
    c.folio_e4,
    c.promedio_final,
        CASE
            WHEN c.promedio_final >= 6::numeric THEN 'aprobado'::text
            WHEN c.promedio_final IS NULL OR c.promedio_final = 0::numeric THEN 'sin_calificar'::text
            ELSE 'reprobado'::text
        END AS estatus_materia,
    (p.nombre || ' '::text) || COALESCE(p.apellido_paterno, ''::text) AS profesor
   FROM alumnos a
     JOIN inscripciones i ON i.alumno_id = a.id
     JOIN grupos g ON g.id = i.grupo_id
     JOIN ciclos_escolares ce ON ce.id = i.ciclo_id
     JOIN asignaciones asig ON asig.grupo_id = g.id AND asig.ciclo_id = ce.id
     JOIN materias m ON m.id = asig.materia_id
     LEFT JOIN calificaciones c ON c.alumno_id = a.id AND c.asignacion_id = asig.id
     LEFT JOIN profesores p ON p.id = asig.profesor_id;

CREATE VIEW public."vista_promedios_semestre" WITH (security_invoker=on) AS SELECT alumno_id,
    curp,
    matricula,
    alumno,
    ciclo,
    periodo,
    grado,
    semestre,
    count(*) AS materias_cursadas,
    count(*) FILTER (WHERE estatus_materia = 'aprobado'::text) AS materias_aprobadas,
    count(*) FILTER (WHERE estatus_materia = 'reprobado'::text) AS materias_reprobadas,
    round(avg(promedio_final) FILTER (WHERE promedio_final > 0::numeric), 2) AS promedio_semestre
   FROM vista_historial_academico
  GROUP BY alumno_id, curp, matricula, alumno, ciclo, periodo, grado, semestre;

CREATE VIEW public."vista_evaluacion_general" WITH (security_invoker=on) AS SELECT alumno_id,
    curp,
    matricula,
    alumno,
    count(DISTINCT semestre) AS semestres_cursados,
    sum(materias_cursadas) AS total_materias,
    sum(materias_aprobadas) AS total_aprobadas,
    sum(materias_reprobadas) AS total_reprobadas,
    round(avg(promedio_semestre), 2) AS promedio_general,
    round(100.0 * sum(materias_aprobadas) / NULLIF(sum(materias_cursadas), 0::numeric), 1) AS porcentaje_avance
   FROM vista_promedios_semestre
  GROUP BY alumno_id, curp, matricula, alumno;

CREATE VIEW public."vista_ficha_alumno" WITH (security_invoker=on) AS SELECT id,
    perfil_id,
    curp,
    matricula,
    nombre,
    apellido_paterno,
    apellido_materno,
    fecha_nacimiento,
    sexo,
    email,
    telefono,
    direccion,
    codigo_postal,
    municipio,
    estado,
    generacion,
    escuela_procedencia,
    promedio_secundaria,
    tutor_nombre,
    tutor_telefono,
    tutor_parentesco,
    tutor_email,
    foto_url,
    observaciones,
    estatus,
    created_at,
    updated_at,
    ( SELECT json_agg(json_build_object('ciclo', ce.codigo, 'periodo', ce.periodo, 'grado', g.grado, 'semestre', g.semestre, 'grupo', g.grupo, 'turno', g.turno, 'fecha_inscripcion', i.fecha_inscripcion, 'estatus', i.estatus) ORDER BY ce.codigo DESC, g.semestre DESC) AS json_agg
           FROM inscripciones i
             JOIN grupos g ON g.id = i.grupo_id
             JOIN ciclos_escolares ce ON ce.id = i.ciclo_id
          WHERE i.alumno_id = a.id) AS inscripciones,
    ( SELECT row_to_json(eg.*) AS row_to_json
           FROM vista_evaluacion_general eg
          WHERE eg.alumno_id = a.id) AS evaluacion_general,
    ( SELECT COALESCE(sum(c.monto), 0::numeric) AS "coalesce"
           FROM cargos c
          WHERE c.alumno_id = a.id AND c.estatus = 'pendiente'::text) AS saldo_pendiente,
    ( SELECT count(*) AS count
           FROM documentos_alumno d
          WHERE d.alumno_id = a.id) AS documentos_expediente
   FROM alumnos a;

CREATE VIEW public."vista_promedios_anuales" WITH (security_invoker=on) AS SELECT alumno_id,
    curp,
    matricula,
    alumno,
        CASE
            WHEN semestre = ANY (ARRAY[1, 2]) THEN 1
            WHEN semestre = ANY (ARRAY[3, 4]) THEN 2
            WHEN semestre = ANY (ARRAY[5, 6]) THEN 3
            ELSE NULL::integer
        END AS anio,
    string_agg(DISTINCT ciclo, ', '::text) AS ciclos,
    sum(materias_cursadas) AS materias_cursadas,
    sum(materias_aprobadas) AS materias_aprobadas,
    sum(materias_reprobadas) AS materias_reprobadas,
    round(avg(promedio_semestre), 2) AS promedio_anual
   FROM vista_promedios_semestre
  GROUP BY alumno_id, curp, matricula, alumno, (
        CASE
            WHEN semestre = ANY (ARRAY[1, 2]) THEN 1
            WHEN semestre = ANY (ARRAY[3, 4]) THEN 2
            WHEN semestre = ANY (ARRAY[5, 6]) THEN 3
            ELSE NULL::integer
        END);

