  WHERE (alumnos.perfil_id = auth.uid()))) OR (alumno_b IN ( SELECT alumnos.id
   FROM alumnos
  WHERE (alumnos.perfil_id = auth.uid())))));

CREATE POLICY "hilos_alumno_select" ON public."hilos_alumno" AS PERMISSIVE FOR SELECT TO "authenticated" USING ((es_admin() OR (alumno_a IN ( SELECT alumnos.id
   FROM alumnos
  WHERE (alumnos.perfil_id = auth.uid()))) OR (alumno_b IN ( SELECT alumnos.id
   FROM alumnos
  WHERE (alumnos.perfil_id = auth.uid())))));

CREATE POLICY "hilos_alumno_update" ON public."hilos_alumno" AS PERMISSIVE FOR UPDATE TO "authenticated" USING (mi_hilo_alumno(id));

CREATE POLICY "security_session_gate" ON public."hilos_alumno" AS RESTRICTIVE FOR ALL TO "authenticated" USING (security_session_valid()) WITH CHECK (security_session_valid());

CREATE POLICY "security_events_admin_read" ON public."security_events" AS PERMISSIVE FOR SELECT TO "authenticated" USING (((( SELECT (auth.jwt() ->> 'aal'::text)) = 'aal2'::text) AND (EXISTS ( SELECT 1
   FROM perfiles p
  WHERE ((p.id = ( SELECT auth.uid() AS uid)) AND (p.rol = ANY (ARRAY['admin'::rol_usuario, 'staff'::rol_usuario, 'director'::rol_usuario])))))));

CREATE POLICY "imports_cred_admin" ON public."imports_credenciales" AS PERMISSIVE FOR ALL TO "authenticated" USING ((EXISTS ( SELECT 1
   FROM perfiles
  WHERE ((perfiles.id = auth.uid()) AND (perfiles.rol = ANY (ARRAY['admin'::rol_usuario, 'staff'::rol_usuario, 'director'::rol_usuario])))))) WITH CHECK ((EXISTS ( SELECT 1
   FROM perfiles
  WHERE ((perfiles.id = auth.uid()) AND (perfiles.rol = ANY (ARRAY['admin'::rol_usuario, 'staff'::rol_usuario, 'director'::rol_usuario]))))));

