     JOIN alumnos al ON ((al.id = i.alumno_id)))
  WHERE (((a.id)::text = split_part(objects.name, '/'::text, 1)) AND (al.perfil_id = auth.uid())))) OR (EXISTS ( SELECT 1
   FROM perfiles
  WHERE ((perfiles.id = auth.uid()) AND (perfiles.rol = ANY (ARRAY['admin'::rol_usuario, 'staff'::rol_usuario, 'director'::rol_usuario]))))))));

